{"explanation":"Drag any point to see the line of best fit update instantly. The line uses least squares: it minimizes the sum of squared vertical distances from the points to the line. The equation and R² update too; R² measures how much of the variation in y the line explains.","manimCode":"const heading = new Text({ text: 'Drag the points. Watch the fit change.', color: WHITE, fontSize: 30 });
heading.moveTo([0, 3.2, 0]);
const hint = new Text({ text: 'Least squares minimizes squared vertical errors', color: GRAY, fontSize: 20 });
hint.moveTo([0, 2.65, 0]);

const ax = new Axes({ xRange: [0, 10, 2], yRange: [0, 10, 2], xLength: 9, yLength: 4.4, tips: false });
ax.moveTo([-0.3, -0.15, 0]);
const origin = ax.c2p(0, 0);
const corner = ax.c2p(10, 10);
const unitX = ax.c2p(1, 0)[0] - origin[0];
const unitY = ax.c2p(0, 1)[1] - origin[1];
const xCaption = new Text({ text: 'x', color: GRAY, fontSize: 22 });
xCaption.moveTo([corner[0] + 0.35, origin[1], 0]);
const yCaption = new Text({ text: 'y', color: GRAY, fontSize: 22 });
yCaption.moveTo([origin[0] - 0.35, corner[1], 0]);

const initial = [[1, 2], [2, 3.4], [3.1, 2.7], [4.2, 5], [5.5, 4.8], [6.4, 7.2], [7.8, 6.4], [9, 8.4]];
const points = initial.map(([x, y]) => new Dot({ point: ax.c2p(x, y), color: TEAL }));
const bestFit = new Polygon({ vertices: [ax.c2p(0, 0), ax.c2p(10, 10)], color: YELLOW });
bestFit.setFillOpacity(0);
bestFit.setStrokeWidth(4);
const residuals = points.map(p => {
  const seg = new Polygon({ vertices: [p.getCenter(), p.getCenter()], color: GRAY });
  seg.setFillOpacity(0);
  seg.setStrokeWidth(1.5);
  seg.setOpacity(0.55);
  return seg;
});
let readout = null;
scene.add(heading, hint, ax, xCaption, yCaption, ...residuals, bestFit, ...points);

function refreshFit() {
  const data = points.map(p => {
    const q = p.getCenter();
    return [(q[0] - origin[0]) / unitX, (q[1] - origin[1]) / unitY];
  });
  const n = data.length;
  const meanX = data.reduce((sum, p) => sum + p[0], 0) / n;
  const meanY = data.reduce((sum, p) => sum + p[1], 0) / n;
  let xx = 0, xy = 0, yy = 0;
  data.forEach(([x, y]) => {
    xx += (x - meanX) ** 2;
    xy += (x - meanX) * (y - meanY);
    yy += (y - meanY) ** 2;
  });
  let caption;
  if (xx < 1e-8) {
    bestFit.setOpacity(0);
    residuals.forEach(seg => seg.setOpacity(0));
    caption = 'Fit undefined: all points have the same x';
  } else {
    const slope = xy / xx;
    const intercept = meanY - slope * meanX;
    const candidates = [];
    function include(x, y) {
      if (x >= -1e-8 && x <= 10 + 1e-8 && y >= -1e-8 && y <= 10 + 1e-8) {
        const q = [Math.max(0, Math.min(10, x)), Math.max(0, Math.min(10, y))];
        if (!candidates.some(p => Math.hypot(p[0] - q[0], p[1] - q[1]) < 1e-7)) candidates.push(q);
      }
    }
    include(0, intercept);
    include(10, slope * 10 + intercept);
    if (Math.abs(slope) > 1e-10) {
      include(-intercept / slope, 0);
      include((10 - intercept) / slope, 10);
    }
    if (candidates.length >= 2) {
      bestFit.setVertices([ax.c2p(...candidates[0]), ax.c2p(...candidates[1])]);
      bestFit.setOpacity(1);
    } else {
      bestFit.setOpacity(0);
    }
    data.forEach(([x, y], i) => {
      const fittedY = Math.max(0, Math.min(10, slope * x + intercept));
      residuals[i].setVertices([ax.c2p(x, y), ax.c2p(x, fittedY)]);
      residuals[i].setOpacity(0.55);
    });
    const rSquared = yy > 1e-8 ? Math.max(0, Math.min(1, xy * xy / (xx * yy))) : null;
    caption = 'y = ' + slope.toFixed(2) + 'x ' + (intercept < 0 ? '- ' : '+ ') + Math.abs(intercept).toFixed(2) + '     |     R² = ' + (rSquared === null ? 'undefined' : rSquared.toFixed(3));
  }
  if (readout) scene.remove(readout);
  readout = new Text({ text: caption, color: YELLOW, fontSize: 24 });
  readout.moveTo([0, -3.1, 0]);
  scene.add(readout);
}

points.forEach(p => {
  makeDraggable(p, scene, {
    constrainX: [Math.min(origin[0], corner[0]), Math.max(origin[0], corner[0])],
    constrainY: [Math.min(origin[1], corner[1]), Math.max(origin[1], corner[1])],
    onDrag: () => refreshFit()
  });
});
refreshFit();
await scene.wait(999999);"}

